    @triton.jit
    def _flagmega_iq4_xs_embedding(weight, token_id, feature, mask, H: tl.constexpr):
        u8 = weight.to(tl.pointer_type(tl.uint8))
        f16 = weight.to(tl.pointer_type(tl.float16))
        u16 = weight.to(tl.pointer_type(tl.uint16))
        block = feature // 256
        inside = feature % 256
        group = inside // 32
        lane = inside % 32
