    import triton.experimental.tle.language as tle
    # flagmega-kernel: dsa_paged_attention/decode
    # flagmega-kernel: mhc_pre/cooperative_contiguous_tf32 platform=nvidia
    import triton.experimental.tle.language as tle
    @triton.jit
    def _flagmega_mhc_contiguous_projection_split(
        streams, projection, split,
        HC: tl.constexpr, HIDDEN: tl.constexpr, SPLITS: tl.constexpr,
        STREAM_STRIDE: tl.constexpr, HIDDEN_STRIDE: tl.constexpr,
        PROJECTION_ROW_STRIDE: tl.constexpr, PROJECTION_HIDDEN_STRIDE: tl.constexpr,
        DOT_LAYOUT: tl.constexpr, SOURCE_LAYOUT: tl.constexpr, MIX_LAYOUT: tl.constexpr,
    ):
        COUNT: tl.constexpr = HC * (HC + 2)
        width: tl.constexpr = HC * HIDDEN // SPLITS
        rows = tl.arange(0, 64)
        cols = tl.arange(0, 32)
        lanes = tl.arange(0, 4)
        accumulator = tl.zeros((64, 32), tl.float32)
        square = tl.zeros((4,), tl.float32)
        for block in tl.range(width // 64):
            flat = split * width + block * 64 + tl.arange(0, 64)
            source = (flat // HIDDEN) * STREAM_STRIDE + (flat % HIDDEN) * HIDDEN_STRIDE
            a = tl.load(streams + source[None, :] + tl.zeros((64, 1), tl.int32),
                        mask=rows[:, None] == 0, other=0.).to(tl.float32)
            b = tl.load(projection + cols[None, :] * PROJECTION_ROW_STRIDE
                        + flat[:, None] * PROJECTION_HIDDEN_STRIDE,
                        mask=cols[None, :] < COUNT, other=0.).to(tl.float32)
            accumulator = tl.dot(a, b, accumulator, input_precision="tf32")
            for pair in tl.static_range(8):
                first = split * width + block * 64 + pair * 8 + lanes
                second = first + 4
                x = tl.load(streams + (first // HIDDEN) * STREAM_STRIDE
                            + (first % HIDDEN) * HIDDEN_STRIDE).to(tl.float32)
                y = tl.load(streams + (second // HIDDEN) * STREAM_STRIDE
                            + (second % HIDDEN) * HIDDEN_STRIDE).to(tl.float32)
                square = libdevice.add_rn(square, tl.fma(x, x, y * y))
        partial = tl.sum(tl.where(rows[:, None] == 0, accumulator, 0.), 0)
        return tle.gpu.set_layout(partial, MIX_LAYOUT), tl.sum(square, 0)


    @triton.jit
    def _flagmega_mhc_contiguous_projection(
        streams, projection,
        HC: tl.constexpr, HIDDEN: tl.constexpr, SPLITS: tl.constexpr,
        STREAM_STRIDE: tl.constexpr, HIDDEN_STRIDE: tl.constexpr,
        PROJECTION_ROW_STRIDE: tl.constexpr, PROJECTION_HIDDEN_STRIDE: tl.constexpr,
        DOT_LAYOUT: tl.constexpr, SOURCE_LAYOUT: tl.constexpr, MIX_LAYOUT: tl.constexpr,
    ):
        mixes = tle.gpu.set_layout(tl.zeros((32,), tl.float32), MIX_LAYOUT)
        square_sum = tl.full((), 0., tl.float32)
        for split in tl.range(SPLITS):
            partial, square = _flagmega_mhc_contiguous_projection_split(
                streams, projection, split, HC, HIDDEN, SPLITS,
                STREAM_STRIDE, HIDDEN_STRIDE, PROJECTION_ROW_STRIDE, PROJECTION_HIDDEN_STRIDE,
                DOT_LAYOUT, SOURCE_LAYOUT, MIX_LAYOUT,
            )
            mixes = libdevice.add_rn(mixes, partial)
            square_sum = libdevice.add_rn(square_sum, square)
        return mixes, square_sum
    # flagmega-kernel: elementwise/mul platform=generic
    # flagmega-kernel-helper: elementwise/packed_axes
    @triton.jit
    def _flagmega_elementwise_packed_offsets(schedule_offsets, schedule_size: tl.constexpr):
        return schedule_offsets, schedule_offsets < schedule_size
    @triton.jit
    def _flagmega_elementwise_mul(lhs, rhs, destination, size: tl.constexpr, block: tl.constexpr):
        schedule_offsets = tl.program_id(0) * 256 + tl.arange(0, 256)
        offsets, mask = _flagmega_elementwise_packed_offsets(schedule_offsets, size)
        tl.store(destination + offsets, tl.load(lhs + offsets, mask=mask) * tl.load(rhs + offsets, mask=mask), mask=mask)
    # flagmega-kernel: gather_reduce_norm_apply/sum platform=generic
    # flagmega-kernel: greedy_sample/distributed_argmax
    @triton.jit
    def _flagmega_argmax_combine(left_value, left_index, right_value, right_index):
        # Match torch.argmax: NaN precedes every numeric value; ties (including
        # two NaNs and infinities) select the lowest logical index, not owner ID.
        left_nan = left_value != left_value
        right_nan = right_value != right_value
        tied = (left_value == right_value) | (left_nan & right_nan)
        take_left = (left_nan & ~right_nan) | (
            ~right_nan & (left_value > right_value)
        ) | (tied & (left_index < right_index))
        return (tl.where(take_left, left_value, right_value),
                tl.where(take_left, left_index, right_index))
    @triton.jit
    def _flagmega_cast_logits_and_local_argmax(
        source, logits, partial_max, partial_index, shard_index,
        VOCAB_SIZE: tl.constexpr, VOCAB_TILE: tl.constexpr,
    ):
        offsets = tl.arange(0, VOCAB_TILE)
        best_value = -float("inf")
        best_index = VOCAB_SIZE
        for start in tl.range(
            shard_index * VOCAB_TILE,
            VOCAB_SIZE,
            512 * VOCAB_TILE,
        ):
            indices = start + offsets
            valid = indices < VOCAB_SIZE
            values = tl.load(source + indices, mask=valid, other=-float("inf")).to(tl.float32)
            tl.store(logits + indices, values, mask=valid)
            tile_max, tile_index = tl.reduce(
                (values, tl.where(valid, indices, VOCAB_SIZE)), 0, _flagmega_argmax_combine)
            best_value, best_index = _flagmega_argmax_combine(
                best_value, best_index, tile_max, tile_index)
        tl.store(partial_max + shard_index, best_value)
        tl.store(partial_index + shard_index, best_index)


    @triton.jit
    def _flagmega_merge_greedy_argmax(
        partial_max, partial_index, next_token, shard_index,
        VOCAB_SIZE: tl.constexpr,
    ):
        if shard_index == 0:
            shards = tl.arange(0, triton.next_power_of_2(512))
            values = tl.load(partial_max + shards, shards < 512, other=-float("inf"))
            indices = tl.load(partial_index + shards, shards < 512, other=VOCAB_SIZE)
            maximum, index = tl.reduce((values, indices), 0, _flagmega_argmax_combine)
            tl.store(next_token, index.to(tl.int32))






