    # flagmega-kernel: gather_reduce_norm_apply/sum platform=generic
    # flagmega-kernel: greedy_sample/distributed_argmax
    @triton.jit
    def _flagmega_argmax_combine(left_value, left_index, right_value, right_index):
        # Match torch.argmax: NaN precedes every numeric value; ties (including
        # two NaNs and infinities) select the lowest logical index, not owner ID.
        left_nan = left_value != left_value
        right_nan = right_value != right_value
        tied = (left_value == right_value) | (left_nan & right_nan)
        take_left = (left_nan & ~right_nan) | (
            ~right_nan & (left_value > right_value)
        ) | (tied & (left_index < right_index))
        return (tl.where(take_left, left_value, right_value),
                tl.where(take_left, left_index, right_index))
    @triton.jit
    def _flagmega_cast_logits_and_local_argmax(
        source, logits, partial_max, partial_index, shard_index,
        VOCAB_SIZE: tl.constexpr, VOCAB_TILE: tl.constexpr,
    ):
        offsets = tl.arange(0, VOCAB_TILE)
        best_value = -float("inf")
        best_index = VOCAB_SIZE
        for start in tl.range(
            shard_index * VOCAB_TILE,
            VOCAB_SIZE,
            512 * VOCAB_TILE,
        ):
            indices = start + offsets
            valid = indices < VOCAB_SIZE
            values = tl.load(source + indices, mask=valid, other=-float("inf")).to(tl.float32)
            tl.store(logits + indices, values, mask=valid)
            tile_max, tile_index = tl.reduce(
                (values, tl.where(valid, indices, VOCAB_SIZE)), 0, _flagmega_argmax_combine)
            best_value, best_index = _flagmega_argmax_combine(
                best_value, best_index, tile_max, tile_index)
        tl.store(partial_max + shard_index, best_value)
        tl.store(partial_index + shard_index, best_index)


    @triton.jit
    def _flagmega_merge_greedy_argmax(
        partial_max, partial_index, next_token, shard_index,
        VOCAB_SIZE: tl.constexpr,
    ):
        if shard_index == 0:
            shards = tl.arange(0, triton.next_power_of_2(512))
            values = tl.load(partial_max + shards, shards < 512, other=-float("inf"))
            indices = tl.load(partial_index + shards, shards < 512, other=VOCAB_SIZE)
            maximum, index = tl.reduce((values, indices), 0, _flagmega_argmax_combine)
            tl.store(next_token, index.to(tl.int32))






    @triton.jit(noinline=True)
    def _flagmega_function_decode_linear_attention_sparse_join__consumer(
        block_local_data,
        device_dptr,
        _flagmega_function_offsets,
        _flagmega_call_pool_workspace,
        _flagmega_call_offsets
    ):
        _flagmega_device_rank = tle.shard_id(FLAGMEGA_GRID_MESH, "device", device_dptr=device_dptr).to(tl.int64)
        shard_coord0 = ((_flagmega_device_rank // 1) % 4)
        shard_coord1 = tle.shard_id(FLAGMEGA_GRID_MESH, 'block_y').to(tl.int64)
        shard_coord2 = tle.shard_id(FLAGMEGA_GRID_MESH, 'block_x').to(tl.int64)
        shard_index = ((shard_coord0 * 8 + shard_coord1) * 16 + shard_coord2)
        block_index = ((0 * 8 + shard_coord1) * 16 + shard_coord2)

        # Same TP4 numerical contract; 16 disjoint owners use the module-owned channel.
        if block_index < 16:
            context = device_dptr
            chip = _flagmega_device_rank.to(tl.int32)
            tile = block_index
            BLOCK: tl.constexpr = 256
            hidden = tile * BLOCK + tl.arange(0, BLOCK)
            window = _flagmega_call_pool_workspace.to(tl.pointer_type(tl.uint8))
            PAYLOAD_BYTES: tl.constexpr = 2914816
            READY_BYTES: tl.constexpr = 2923008
            CONSUMED_BYTES: tl.constexpr = 2923136
            residual = tl.multiple_of(window + tl.load(_flagmega_call_offsets + 0, volatile=True), 256).to(tl.pointer_type(tl.float32))
            post = tl.multiple_of(window + tl.load(_flagmega_call_offsets + 1, volatile=True), 256).to(tl.pointer_type(tl.float32))
            comb = tl.multiple_of(window + tl.load(_flagmega_call_offsets + 2, volatile=True), 256).to(tl.pointer_type(tl.float32))
            coeff = tl.multiple_of(window + tl.load(_flagmega_call_offsets + 3, volatile=True), 256).to(tl.pointer_type(tl.float32))
            routed = tl.multiple_of(window + tl.load(_flagmega_call_offsets + 5, volatile=True), 256).to(tl.pointer_type(tl.float32))
            shared = tl.multiple_of(window + tl.load(_flagmega_call_offsets + 6, volatile=True), 256).to(tl.pointer_type(tl.bfloat16))
            output = tl.multiple_of(window + tl.load(_flagmega_call_offsets + 7, volatile=True), 256).to(tl.pointer_type(tl.float32))
            ready = (window + READY_BYTES).to(tl.pointer_type(tl.uint64)) + tile
            consumed = (window + CONSUMED_BYTES).to(tl.pointer_type(tl.uint64)) + tile
            epoch = tl.atomic_add(ready, 0, sem='relaxed', scope='sys') + 1
            p0 = tl.multiple_of(tle.remote(context, space='device', dtype=tl.uint8, shard_id=0, offset=0), 4096)
            p1 = tl.multiple_of(tle.remote(context, space='device', dtype=tl.uint8, shard_id=1, offset=0), 4096)
            p2 = tl.multiple_of(tle.remote(context, space='device', dtype=tl.uint8, shard_id=2, offset=0), 4096)
            p3 = tl.multiple_of(tle.remote(context, space='device', dtype=tl.uint8, shard_id=3, offset=0), 4096)
            peer = tl.arange(0, 4)
            bases = tl.where(peer == 0, p0, tl.where(peer == 1, p1, tl.where(peer == 2, p2, p3)))
            pointers = (bases + CONSUMED_BYTES + tile * 8).to(tl.pointer_type(tl.uint64))
            observed = tl.atomic_add(pointers, tl.full((4,), 0, tl.uint64), sem='acquire', scope='sys')
            while tl.min(observed, 0) < epoch - 1:
                observed = tl.atomic_add(pointers, tl.full((4,), 0, tl.uint64), sem='acquire', scope='sys')
            tl.debug_barrier()
            weighted = tl.full((BLOCK,), 0, tl.float32)
            for route in tl.range(0, 8, loop_unroll_factor=1):
                value = tl.load(routed + chip * 32768 + route * 4096 + hidden)
                scale = tl.load(coeff + route)
                term = libdevice.mul_rn(value, scale).to(tl.bfloat16).to(tl.float32)
                weighted = libdevice.add_rn(weighted, term)
            weighted = weighted.to(tl.bfloat16).to(tl.float32)
            local = libdevice.add_rn(weighted, tl.load(shared + hidden).to(tl.float32))
            local = local.to(tl.bfloat16).to(tl.float32)
            local = libdevice.add_rn(tl.full((BLOCK,), 0, tl.float32), local).to(tl.bfloat16)
            payload = (window + PAYLOAD_BYTES).to(tl.pointer_type(tl.bfloat16))
            tl.store(payload + hidden, local)
            tl.debug_barrier()
            tl.atomic_xchg(ready, epoch, sem='release', scope='sys')
            pointers = (bases + READY_BYTES + tile * 8).to(tl.pointer_type(tl.uint64))
            observed = tl.atomic_add(pointers, tl.full((4,), 0, tl.uint64), sem='acquire', scope='sys')
            while tl.min(observed, 0) < epoch:
                observed = tl.atomic_add(pointers, tl.full((4,), 0, tl.uint64), sem='acquire', scope='sys')
            tl.debug_barrier()
            v0 = tl.load((p0 + PAYLOAD_BYTES).to(tl.pointer_type(tl.bfloat16)) + hidden).to(tl.float32)
            v1 = tl.load((p1 + PAYLOAD_BYTES).to(tl.pointer_type(tl.bfloat16)) + hidden).to(tl.float32)
            v2 = tl.load((p2 + PAYLOAD_BYTES).to(tl.pointer_type(tl.bfloat16)) + hidden).to(tl.float32)
            v3 = tl.load((p3 + PAYLOAD_BYTES).to(tl.pointer_type(tl.bfloat16)) + hidden).to(tl.float32)
            reduced = libdevice.add_rn(tl.full((BLOCK,), 0, tl.float32), v0)
            reduced = libdevice.add_rn(reduced, v1)
            reduced = libdevice.add_rn(reduced, v2)
            reduced = libdevice.add_rn(reduced, v3)
            reduced = reduced.to(tl.bfloat16).to(tl.float32)
            tl.debug_barrier()
            tl.atomic_xchg(consumed, epoch, sem='release', scope='sys')
            r0 = tl.load(residual + hidden).to(tl.bfloat16).to(tl.float32)
            r1 = tl.load(residual + 4096 + hidden).to(tl.bfloat16).to(tl.float32)
            r2 = tl.load(residual + 8192 + hidden).to(tl.bfloat16).to(tl.float32)
            r3 = tl.load(residual + 12288 + hidden).to(tl.bfloat16).to(tl.float32)
            for sink in tl.static_range(4):
                result = libdevice.mul_rn(tl.load(comb + sink), r0)
                result = tl.fma(tl.load(post + sink), reduced, result)
                result = tl.fma(tl.load(comb + 4 + sink), r1, result)
                result = tl.fma(tl.load(comb + 8 + sink), r2, result)
                result = tl.fma(tl.load(comb + 12 + sink), r3, result)
                tl.store(output + sink * 4096 + hidden, result)


