        sl = tl.load(u8 + base + 4 + group // 2, mask=mask, other=0)
        sh = tl.load(u16 + (base + 2) // 2, mask=mask, other=0)
        sc = ((sl >> ((group % 2) * 4)) & 0xF) | (((sh >> (group * 2)) & 0x3) * 16)
