    @triton.jit
    def _flagmega_norm_stats_finalize(values):
        if values.shape[0] >= 32 and values.shape[0] <= 256:
            rows = tl.reshape(values, (values.shape[0] // 32, 32))
            rows = tle.gpu.set_layout(rows, FLAGMEGA_NORM_WARP_ROWS)
